{"description":"Rename remaining prompt files and update manifests","command":".local_tools/node-v22.14.0-linux-x64/bin/node -e '
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

const root = "office-equity-modernization-prompt-pack";
const promptsDir = path.join(root, "prompts");
const indexFile = path.join(root, "manifests", "PROMPT_INDEX.md");
const shaFile = path.join(root, "manifests", "SHA256SUMS.txt");

function getModelSlug(executionClass) {
  if (executionClass.includes("3.6 Flash")) return "gemini_3.6_flash";
  if (executionClass.includes("3.5 Flash-Lite")) return "gemini_3.5_flash_lite";
  if (executionClass.includes("3.1 Pro")) return "gemini_3.1_pro";
  return "unknown";
}

const files = fs.readdirSync(promptsDir).sort();
const renameMap = {};

for (const file of files) {
  if (file === "00_LOCAL_EXECUTOR_PREAMBLE.md" || file.startsWith("01_") || file.startsWith("02_") || file.startsWith("03_")) {
    continue;
  }
  const content = fs.readFileSync(path.join(promptsDir, file), "utf8");
  const match = content.match(/\*\*Execution class:\*\*\s*(.*)/);
  const execClass = match ? match[1] : "";
  const modelSlug = getModelSlug(execClass);
  const num = file.slice(0, 3);
  const rest = file.slice(3);
  const newName = `${num}${modelSlug}_${rest}`;
  renameMap[file] = newName;

  fs.renameSync(path.join(promptsDir, file), path.join(promptsDir, newName));
  console.log(`Renamed: ${file} -> ${newName}`);
}

// Update PROMPT_INDEX.md
if (fs.existsSync(indexFile)) {
  let indexContent = fs.readFileSync(indexFile, "utf8");
  for (const [oldName, newName] of Object.entries(renameMap)) {
    indexContent = indexContent.replace(new RegExp(oldName, "g"), newName);
  }
  fs.writeFileSync(indexFile, indexContent, "utf8");
  console.log("Updated PROMPT_INDEX.md");
}

// Update SHA256SUMS.txt
const manifestFiles = [
  "MASTER_MODERNIZATION_AND_EFFICIENCY_PLAN.md",
  "MASTER_MODERNIZATION_AND_EFFICIENCY_PLAN.pre-local-llm.md",
  "README.md",
  "manifests/PROMPT_INDEX.md",
];

const promptFiles = fs.readdirSync(promptsDir).sort();
let shaLines = [];

for (const mf of manifestFiles) {
  const p = path.join(root, mf);
  if (fs.existsSync(p)) {
    const data = fs.readFileSync(p);
    const hash = crypto.createHash("sha256").update(data).digest("hex");
    shaLines.push(`${hash}  ${mf}`);
  }
}

for (const pf of promptFiles) {
  const p = path.join(promptsDir, pf);
  const data = fs.readFileSync(p);
  const hash = crypto.createHash("sha256").update(data).digest("hex");
  shaLines.push(`${hash}  prompts/${pf}`);
}

fs.writeFileSync(shaFile, shaLines.join("\n") + "\n", "utf8");
console.log("Updated SHA256SUMS.txt");
'"}

